import{_ as t,c as i,o as a,a3 as n}from"./chunks/framework.Cc9k46oU.js";const g=JSON.parse(`{"title":"Scrumban Operations Guide","description":"Scrumban is a hybrid Agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits for flexible, efficient work management.","frontmatter":{"title":"Scrumban Operations Guide","description":"Scrumban is a hybrid Agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits for flexible, efficient work management.","head":[["meta",{"name":"keywords","content":"Scrumban, Scrumban overview, Scrumban concepts, what is Scrumban, Scrum vs Kanban, Agile methodology, Agile framework, Kanban methodology, Scrum methodology, Scrumban process, Scrumban operations guide, Scrumban board, WIP limits, workflow management, Kanban board usage, Scrumban benefits, Scrumban features, Scrumban use cases, Scrumban Jira setup, Scrumban board template, Scrumban tools, Scrumban collaboration tools, Scrumban workflow, Agile project management, work efficiency methodology, iterative task management, bottleneck resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid Agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits for flexible, efficient work management."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/guide"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/agile/guide"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/guide"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/guide"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/guide"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Scrumban Operations Guide | Empasy Docs"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid Agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits for flexible, efficient work management."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/guide"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Scrumban Operations Guide | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Scrumban is a hybrid Agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits for flexible, efficient work management."}]],"sort":300},"headers":[],"relativePath":"en/agile/guide.md","filePath":"en/agile/guide.md","lastUpdated":1795293539000}`),r={name:"en/agile/guide.md"};function o(s,e,l,d,c,m){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="scrumban-standard-operations-guide" tabindex="-1">Scrumban Standard Operations Guide <a class="header-anchor" href="#scrumban-standard-operations-guide" aria-label="Permalink to “Scrumban Standard Operations Guide”">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to “1. Overview”">​</a></h2><p>Scrumban is a hybrid process that combines the structure of <strong>Scrum</strong> with the flexible flow management of <strong>Kanban</strong>.</p><ul><li>Rules, roles, and backlog management provided by <strong>Scrum</strong></li><li>WIP limits, pull systems, and flow visualization provided by <strong>Kanban</strong> Combining these two enables teams to <strong>adapt rapidly to change</strong> and <strong>optimize workflow</strong>.</li></ul><blockquote><p><strong>Core Philosophy</strong> &quot;<strong>Stop starting, start finishing</strong>&quot; — Finish work already in progress rather than starting new work.</p></blockquote><hr><h2 id="_2-core-principles" tabindex="-1">2. Core Principles <a class="header-anchor" href="#_2-core-principles" aria-label="Permalink to “2. Core Principles”">​</a></h2><ol><li><strong>Pull-Based Work</strong></li></ol><ul><li>Work is started only when the team has the capacity to handle it.</li><li>Forcefully &quot;pushing&quot; work into the pipeline disrupts the flow.</li></ul><ol start="2"><li><strong>WIP (Work In Progress) Limits</strong></li></ol><ul><li>Limit the number of items in progress concurrently to prevent quality degradation and multitasking overhead.</li><li>Example: For a 5-person team, <code>Doing WIP = 3</code>.</li></ul><ol start="3"><li><strong>Workflow Visualization</strong></li></ol><ul><li>Make every work item&#39;s status visible at a glance on a Kanban board.</li><li>Bottlenecks can be identified immediately.</li></ul><ol start="4"><li><strong>Explicit Policies</strong></li></ol><ul><li>Document the entry/exit criteria for moving items into each column (such as Definition of Ready and Definition of Done) and share them across the entire team.</li></ul><ol start="5"><li><strong>Data-Driven Improvement</strong></li></ol><ul><li>Measure Cycle Time, Throughput, WIP, and CFD (Cumulative Flow Diagram) to guide process improvements.</li></ul><hr><h2 id="_3-roles-and-responsibilities" tabindex="-1">3. Roles and Responsibilities <a class="header-anchor" href="#_3-roles-and-responsibilities" aria-label="Permalink to “3. Roles and Responsibilities”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Primary Responsibilities</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Product Owner (PO)</strong></td><td>Backlog management, prioritization, requirement clarification, communicating business goals</td><td>Retained directly from Scrum</td></tr><tr><td><strong>Flow Manager / Scrum Master</strong></td><td>WIP monitoring, removing blockers, facilitating retrospectives, driving process improvement</td><td>Similar to Kanban&#39;s Service Delivery Manager role</td></tr><tr><td><strong>Team Members (Dev, QA, etc.)</strong></td><td>Adhering to WIP limits, pull-based execution, updating card statuses, ensuring quality</td><td>Requires autonomy and ownership</td></tr><tr><td><strong>Stakeholders</strong></td><td>Providing feedback, participating in demos and reviews</td><td>Regular engagement required</td></tr></tbody></table><hr><h2 id="_4-activities-by-process-stage" tabindex="-1">4. Activities by Process Stage <a class="header-anchor" href="#_4-activities-by-process-stage" aria-label="Permalink to “4. Activities by Process Stage”">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Activity</th><th>Detailed Description</th><th>Policy (Example)</th></tr></thead><tbody><tr><td><strong>Backlog</strong></td><td>Request and idea intake</td><td>Starting point for all work, including customer requests, bugs, tech debt, and new features</td><td>Assign priority and Class of Service to every card</td></tr><tr><td><strong>Ready</strong></td><td>DoR verification, work prepared</td><td>Clarify requirements, secure resources, define test conditions</td><td>Move only after passing the DoR checklist</td></tr><tr><td><strong>Doing</strong></td><td>Work execution</td><td>Pull within WIP limit and carry out development/implementation</td><td><code>Doing WIP = 3</code></td></tr><tr><td><strong>Review</strong></td><td>Code and document review</td><td>Verify quality, standards, security, and test coverage</td><td>Move to Testing upon reviewer approval</td></tr><tr><td><strong>Testing</strong></td><td>Quality verification</td><td>Automated and manual testing, defect resolution</td><td>Move to Done upon QA sign-off</td></tr><tr><td><strong>Done</strong></td><td>Work completion</td><td>Meet DoD, complete documentation/deployment, record Cycle Time</td><td>Apply completion tag</td></tr></tbody></table><hr><h2 id="_5-definition-criteria" tabindex="-1">5. Definition Criteria <a class="header-anchor" href="#_5-definition-criteria" aria-label="Permalink to “5. Definition Criteria”">​</a></h2><h3 id="_5-1-definition-of-ready-dor" tabindex="-1">5.1 Definition of Ready (DoR) <a class="header-anchor" href="#_5-1-definition-of-ready-dor" aria-label="Permalink to “5.1 Definition of Ready (DoR)”">​</a></h3><ul><li>Requirements are clear and documented</li><li>Required designs and resources are secured</li><li>Test conditions are defined</li><li>Estimated scope and complexity are confirmed</li></ul><h3 id="_5-2-definition-of-done-dod" tabindex="-1">5.2 Definition of Done (DoD) <a class="header-anchor" href="#_5-2-definition-of-done-dod" aria-label="Permalink to “5.2 Definition of Done (DoD)”">​</a></h3><ul><li>Code merged and build succeeds</li><li>Automated and manual tests pass</li><li>Documentation and release notes written</li><li>Deployed (or delivered to the customer)</li></ul><hr><h2 id="_6-meeting-event-operations-guide" tabindex="-1">6. Meeting (Event) Operations Guide <a class="header-anchor" href="#_6-meeting-event-operations-guide" aria-label="Permalink to “6. Meeting (Event) Operations Guide”">​</a></h2><table tabindex="0"><thead><tr><th>Meeting</th><th>Purpose</th><th>Cadence</th><th>Duration</th><th>Characteristics</th></tr></thead><tbody><tr><td><strong>Daily Stand-up</strong></td><td>Share progress and blockers</td><td>Daily</td><td>10–15 min</td><td>Discuss focused on column flow</td></tr><tr><td><strong>Replenishment</strong></td><td>Refill the Ready column</td><td>Weekly or at threshold</td><td>30 min</td><td>Re-align priorities</td></tr><tr><td><strong>Retrospective</strong></td><td>Process improvement</td><td>Every 2–4 weeks</td><td>30–60 min</td><td>Adjust WIP limits and policies</td></tr><tr><td><strong>Service Delivery Review</strong></td><td>Review SLA/SLE compliance</td><td>Monthly</td><td>30 min</td><td>Metrics-driven review</td></tr></tbody></table><hr><h2 id="_7-wip-limit-operations" tabindex="-1">7. WIP Limit Operations <a class="header-anchor" href="#_7-wip-limit-operations" aria-label="Permalink to “7. WIP Limit Operations”">​</a></h2><ul><li><p>Initial value: <code>Team size ÷ 2</code></p></li><li><p>Example WIP limits per column:</p><ul><li>Doing: 3</li><li>Review: 2</li><li>Testing: 2</li></ul></li><li><p>If WIP exceeds the limit, immediately analyze the root cause (bottlenecks, staffing gaps, blockers, etc.)</p></li><li><p>Prohibit starting new work until the excess is resolved</p></li></ul><hr><h2 id="_8-metrics-management" tabindex="-1">8. Metrics Management <a class="header-anchor" href="#_8-metrics-management" aria-label="Permalink to “8. Metrics Management”">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Definition</th><th>Usage</th></tr></thead><tbody><tr><td><strong>Lead Time</strong></td><td>Request created → Done</td><td>Analyze customer wait time</td></tr><tr><td><strong>Cycle Time</strong></td><td>Work started → Done</td><td>Measure flow stability</td></tr><tr><td><strong>Throughput</strong></td><td>Number of cards completed per period</td><td>Forecast productivity</td></tr><tr><td><strong>Average WIP</strong></td><td>Average number of items in progress</td><td>Prevent bottlenecks and multitasking</td></tr><tr><td><strong>CFD</strong></td><td>Cumulative item count per column</td><td>Identify bottleneck stages</td></tr></tbody></table><blockquote><p><strong>Tip:</strong> Applying Little&#39;s Law <code>WIP = Throughput × Cycle Time</code> → Adjusting any one of WIP, Throughput, or Cycle Time changes the others.</p></blockquote><hr><h2 id="_9-sample-operating-rules" tabindex="-1">9. Sample Operating Rules <a class="header-anchor" href="#_9-sample-operating-rules" aria-label="Permalink to “9. Sample Operating Rules”">​</a></h2><ol><li>Always check WIP limits before pulling work</li><li>Assign a priority and owner to every card</li><li>Flag blockers immediately (stickers or labels)</li><li>Strictly timebox meetings (Stand-up ≤ 15 min)</li><li>Apply process changes only after team consensus in a Retrospective</li></ol><hr><h2 id="_10-process-visualization-example" tabindex="-1">10. Process Visualization Example <a class="header-anchor" href="#_10-process-visualization-example" aria-label="Permalink to “10. Process Visualization Example”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Backlog]</span></span>
<span class="line"><span>  ↓ (Replenishment)</span></span>
<span class="line"><span>[Ready]</span></span>
<span class="line"><span>  ↓ (Pull &amp; WIP Check)</span></span>
<span class="line"><span>[Doing]</span></span>
<span class="line"><span>  ↓ (Development Complete)</span></span>
<span class="line"><span>[Review]</span></span>
<span class="line"><span>  ↓ (Review Approved)</span></span>
<span class="line"><span>[Testing]</span></span>
<span class="line"><span>  ↓ (QA Passed)</span></span>
<span class="line"><span>[Done]</span></span></code></pre></div><hr><h2 id="_11-improvement-cycle" tabindex="-1">11. Improvement Cycle <a class="header-anchor" href="#_11-improvement-cycle" aria-label="Permalink to “11. Improvement Cycle”">​</a></h2><ol><li>Collect metrics (Cycle Time, Throughput, WIP)</li><li>Analyze bottlenecks and variability</li><li>Adjust WIP limits, policies, and board structure</li><li>Run a 1–2 week trial</li><li>Validate impact in the Retrospective and finalize</li></ol><hr><h2 id="_12-appendix" tabindex="-1">12. Appendix <a class="header-anchor" href="#_12-appendix" aria-label="Permalink to “12. Appendix”">​</a></h2><h3 id="sample-classes-of-service" tabindex="-1">Sample Classes of Service <a class="header-anchor" href="#sample-classes-of-service" aria-label="Permalink to “Sample Classes of Service”">​</a></h3><ul><li><strong>Expedite</strong>: Immediate handling (urgent)</li><li><strong>Fixed Date</strong>: Hard deadline on a specific date</li><li><strong>Standard</strong>: Regular requests</li><li><strong>Intangible</strong>: Long-term value such as technical debt</li></ul><h3 id="recommended-tools" tabindex="-1">Recommended Tools <a class="header-anchor" href="#recommended-tools" aria-label="Permalink to “Recommended Tools”">​</a></h3><ul><li>Jira, Trello, Azure DevOps, Miro, ClickUp</li></ul><hr><p><strong>Key Takeaway</strong> Scrumban is a methodology focused on &quot;<strong>keeping rules minimal while optimizing flow</strong>.&quot; The process must continuously evolve based on the team&#39;s <strong>data and consensus</strong>.</p><hr>`,57)])])}const h=t(r,[["render",o]]);export{g as __pageData,h as default};
